/* The floor lead's investigation desk. All amounts come from the dashboard export. */
(()=>{'use strict';
const E=window.AceEvidence,D=E.data,A=D.advanced,$=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n),num=n=>Math.round(n).toLocaleString('en-US'),pct=n=>(100*n).toFixed(1)+'%',sign=n=>(n>=0?'+':'')+pct(n);
const tabs=[['brief','♠ Decision'],['machines','♜ The shortlist'],['movers','♦ Location'],['operations','♥ Downtime'],['guests','♣ Guest desk'],['forecast','✦ Forecast'],['plan','✓ Your plan']];
let tab='brief',filters={from:0,to:5,zone:'',bank:'',tier:'',region:''},selected='M-1158',metric='houseWin',mover='M-1152',period='after',retention=50,tourIndex=0,judgments={};
try{judgments=JSON.parse(localStorage.getItem('ace-investigation-notes')||'{}');if(!judgments||typeof judgments!=='object')judgments={};}catch{}
const visited=new Set();
const table=(heads,rows)=>`<div class="desk-scroll"><table class="desk-table"><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const kpis=rows=>`<div class="desk-kpis">${rows.map(r=>`<div><small>${r[0]}</small><b>${r[1]}</b></div>`).join('')}</div>`;
const scope=text=>`<p class="scope">${text}</p>`;
const opts=(values,current,all)=>`${all?`<option value="">${all}</option>`:''}${values.map(v=>`<option value="${esc(v)}" ${String(v)===String(current)?'selected':''}>${esc(v)}</option>`).join('')}`;
const bars=(rows,label,format=money)=>{const max=Math.max(1,...rows.map(r=>Math.abs(r[1])));return `<div role="img" aria-label="${esc(label)}">${rows.map(r=>`<div class="desk-bar-row"><span>${r[0]}</span><div class="desk-bar"><i style="width:${Math.abs(r[1])/max*100}%"></i></div><b>${format(r[1])}</b></div>`).join('')}</div>`;};
const periodText=()=>`${D.months[filters.from]} → ${D.months[filters.to]}`;
function filterUI(guest=false){return `<div class="desk-filters"><label>From<select id="deskFrom" aria-label="From">${D.months.map((m,i)=>`<option value="${i}" ${i===filters.from?'selected':''}>${m}</option>`).join('')}</select></label><label>Through<select id="deskTo" aria-label="Through">${D.months.map((m,i)=>`<option value="${i}" ${i===filters.to?'selected':''}>${m}</option>`).join('')}</select></label>${guest?`<label>Opening tier<select id="deskTier" aria-label="Opening tier">${opts([...new Set(D.players.map(r=>r[1]))],filters.tier,'All tiers')}</select></label><label>Home region<select id="deskRegion" aria-label="Home region">${opts([...new Set(D.players.map(r=>r[2]))],filters.region,'All regions')}</select></label>`:`<label>Zone<select id="deskZone" aria-label="Zone">${opts([...new Set(D.machines.flatMap(m=>m.segments.map(s=>s[1])))].sort(),filters.zone,'All zones')}</select></label><label>Bank<select id="deskBank" aria-label="Bank">${opts([...new Set(D.machines.flatMap(m=>m.segments.filter(s=>!filters.zone||s[1]===filters.zone).map(s=>s[2])))].sort(),filters.bank,'All banks')}</select></label>`}<button class="quiet" data-reset-filters>Reset filters</button></div>`;}
function verdict(){return `<h3>The original ten: our July decisions</h3>${scope('FIXED · Jan–Jun lowest actual earners · all play · not changed by workspace filters')}<p>Inspect one, verify two inactive IDs, and keep the other seven under review. These are analyst judgments, not proven treatment effects. No blanket replacement is supported.</p>${table(['Machine','Next step','Evidence','Uncertainty / check'],window.AceDecision.shortlist().map(m=>[`<button data-original="${m.id}">${m.id}</button>`,m.action,m.reason,m.uncertainty]))}<p class="note">Click a machine to inspect its full-window evidence. Source: machine meters, game math and dated active placements. Off-floor days are excluded; availability and expected win use ratios of sums. The funded plan is one inspection only; placement reviews do not imply funded moves.</p>`;}
function brief(){const s=window.AceDecision.schedule();return `<div class="eyebrow">THE MANAGER’S ANSWER</div><h3>Inspect first. Keep $98,800.</h3><p>Fund a $1,200 inspection of M-1158 before authorizing a replacement or repair.</p><p class="desk-note"><b>When:</b> ${s.day}, ${s.label}, 2025 is the first quietest-weekday slot after the ${s.lead}-day lead time. Confirm staffing. The Jan–Apr model informs timing, not the benefit of inspection.</p><div class="actions"><button class="outline" data-evidence="plan">Trace the recommendation ↗</button><button class="outline" data-desk="forecast">Check model validation ↗</button></div>${verdict()}<button class="outline" data-desk="machines">Explore periods and banks ↗</button>`;}
function machines(){const all=E.machines(filters),raw=[...all].sort((a,b)=>a.houseWin-b.houseWin),ranked=[...all].sort((a,b)=>a[metric]-b[metric]),short=raw.slice(0,10);let m=all.find(m=>m.id===selected)||short[0];if(m)selected=m.id;
 const peers=m?all.filter(p=>p.id!==m.id&&p.cfg===m.cfg):[],ph=peers.reduce((s,p)=>s+p.availH,0),peerRate=ph?peers.reduce((s,p)=>s+p.theo,0)/ph:null;
 return `<div class="eyebrow">CASE 01 · THE MISLEADING SHORTLIST</div><h3>Low earnings are the beginning of the story.</h3>${filterUI()}${scope(`FILTERED · ${periodText()} · ${filters.zone||'All zones'} · ${filters.bank||'All banks'} · all play · dated placements, active days only`)}<div class="desk-filters"><label>Rank lowest first by<select id="rankMetric" aria-label="Rank lowest first by"><option value="houseWin" ${metric==='houseWin'?'selected':''}>Actual house win</option><option value="tph" ${metric==='tph'?'selected':''}>Expected win / available hour</option><option value="availability" ${metric==='availability'?'selected':''}>Availability</option></select></label></div><p class="note">The ten lowest under your selected measure. Start with actual earnings, then switch measures to challenge the shortlist. This is a schematic shortlist, not a geographic floor plan.</p><div class="floor-map">${ranked.slice(0,10).map(x=>`<button class="floor-machine" data-machine="${x.id}" aria-pressed="${x.id===selected}"><b>${x.id}</b><small>${metric==='availability'?pct(x.availability):metric==='tph'?money(x.tph)+' / h':money(x.houseWin)}</small><small>${esc(x.locations[0]?.split(' / ')[0]||'')}</small></button>`).join('')}</div>${!m?'<p class="desk-empty">No active machines in this selection. Change or reset filters.</p>':`<div class="desk-grid"><div><h3>${m.id} <small style="font-size:14px">${esc(m.theme)}</small></h3><p class="note">${m.locations.map(esc).join(' → ')} · ${esc(m.cfg)}</p>${kpis([['Actual house win',money(m.houseWin)],['Expected house win',money(m.theo)],['Availability',pct(m.availability)],['Expected win / available h',money(m.tph)],['Luck residual / SD',m.luckZ.toFixed(2)],['Same-game peers / h',peerRate==null?'No peers':money(peerRate)]])}${bars([['Actual',m.houseWin],['Expected',m.theo]],'Actual versus expected house win')}<p class="note">Actual − expected: ${money(m.houseWin-m.theo)}. Expected win uses game math; it is not a forecast. The standardized residual is a descriptive diagnostic, not a multiple-testing-adjusted fault test. Peer rate uses ${peers.length} other machines in this selection, not a causal match.</p></div><div><h3>Your provisional call</h3><p>Save a provisional note. The evidence and limitations should guide your decision.</p><div class="decision-tags">${['Keep','Inspect','Repair','Consider moving','Need more evidence'].map(v=>`<button data-judgment="${v}" aria-pressed="${judgments[selected]===v}">${v}</button>`).join('')}</div><p id="judgmentFeedback" role="status" class="desk-note">${judgments[selected]?`Saved: ${esc(judgments[selected])}. This is your provisional assessment, not a verified recommendation.`:'A defensible decision can be “need more evidence.” Low earnings alone do not justify replacement.'}</p><button class="outline" data-evidence="machines">How to read these numbers ↗</button><div class="study-option"><b>Check operations</b><p>${num(m.schedH-m.availH)} unavailable hours, ${num(m.faults)} fault tickets in this selection. Missing availability can explain reduced exposure.</p></div></div></div>`}<details><summary>Compare the ten lowest machines under your selected ranking</summary>${table(['Machine','Actual win','Expected / available h','Availability','Raw-win shortlist?'],ranked.slice(0,10).map(x=>[`<button data-machine="${x.id}">${x.id}</button>`,money(x.houseWin),money(x.tph),pct(x.availability),short.some(s=>s.id===x.id)?'Yes':'No']))}</details><button class="desk-link" data-desk="movers">Next investigation: did location matter? →</button>`;}
function movers(){const m=A.movers.find(m=>m.id===mover),after=period==='after';const weeks=D.zoneWeek.filter(r=>r[0]==='Back Forty');return `<div class="eyebrow">CASE 02 · A CHANGE OF SCENERY</div><h3>Same machine. Different place.</h3>${scope(`FIXED STUDY · ${m.daysEachSide} days either side of ${m.date} · move day excluded · global period filters do not apply`)}<div class="desk-filters"><label>Investigate a mover<select id="deskMover" aria-label="Investigate a mover">${opts(A.movers.map(m=>m.id),mover)}</select></label><label>Window<select id="movePeriod" aria-label="Window"><option value="before" ${!after?'selected':''}>Before the move</option><option value="after" ${after?'selected':''}>After the move</option></select></label></div><p>${esc(m.from)} → <b>${esc(m.to)}</b></p>${bars([['Moved machine',after?m.postTph:m.preTph],['Same-game stayers',after?m.controlPostTph:m.controlPreTph]],'Expected win per available hour, selected move window')}${kpis([['Relative change vs stayers',sign(m.relativeEffect)],['95% block interval',`${sign(m.ci95[0])} to ${sign(m.ci95[1])}`],['Source-zone controls',m.controls]])}<p class="desk-note">${m.ci95[0]>0?'This is a strong location clue. It does not establish that the casino gained new revenue.':'The interval includes no change. This move does not establish a reliable improvement.'} Moves were not randomized; selection and customer displacement remain alternatives.</p>${table(['All four moves','Relative change','95% interval'],A.movers.map(x=>[`<button data-mover="${x.id}">${x.id}</button>`,sign(x.relativeEffect),`${sign(x.ci95[0])} to ${sign(x.ci95[1])}`]))}<details><summary>Was Back Forty already declining before the closure?</summary>${scope('FIXED · Jan 6–Mar 2 · Back Forty versus other zones · no global filters')}${bars(A.pretrend.weekly.map(r=>[r[0],r[1]/r[2]*100]),'Back Forty / other-zone expected win per hour ratio; values scaled by 100',v=>v.toFixed(1)+'%')}<p>Pre-closure relative trend: ${sign(A.pretrend.relativeSlopePerWeek)} per week. Balanced-panel check: ${sign(A.pretrend.balancedPanelSlopePerWeek)}. The earlier decline weakens a claim that the closure alone caused the later difference.</p>${table(['Week','Back Forty theo/h','Other zones theo/h'],A.pretrend.weekly.map(r=>[r[0],money(r[1]),money(r[2])]))}</details><details><summary>Demand over the six months</summary>${scope('FIXED · weekly Back Forty expected win per available hour · no global filters')}${table(['Week','Expected win / available h'],weeks.map(r=>[r[1].slice(0,10),money(r[2])]))}<a href="dashboard.html#q2">Compare every zone in the dashboard ↗</a></details><button class="outline" data-evidence="movers">Trace this location finding ↗</button>`;}
function operations(){const L=A.matchedDowntime,loss=L.lostTheo*(1-retention/100);return `<div class="eyebrow">CASE 03 · THE MISSING PLAY</div><h3>Did the play leave the casino?</h3>${scope('FIXED · Jan–Jun · same configuration, actual zone, weekday and local-hour peers · global filters do not apply')}${kpis([['Machine-level expected win forgone',money(L.lostTheo)],['Unavailable machine-hours',num(L.downHours)],['Zone-matched downtime coverage',pct(L.zoneMatchedShare)]])}<label for="deskRetention">Play retained on other casino machines: <b id="retentionLabel">${retention}%</b></label><input id="deskRetention" type="range" min="0" max="100" step="5" value="${retention}"><div id="retentionResult" aria-live="polite">${bars([['Machine-level',L.lostTheo],['Property-level',loss]],'Machine and property-level expected win forgone')}<p class="desk-note">At ${retention}% retention, ${money(loss)} expected house win is forgone property-wide. This is before incremental costs; it is not lost profit.</p></div><p class="note">Customer switching is a sensitivity assumption, not observed behavior. Sparse peer cells fall back across zones; the target machine is excluded from its own peer rate.</p><details><summary>When was expected win forgone?</summary>${table(['Local hour','Peer-matched theo forgone'],L.hourly.map(r=>[String(r[0]).padStart(2,'0')+':00',money(r[1])]))}</details><button class="outline" data-evidence="operations">Check the matching and limitations ↗</button>`;}
function guests(){const {totals:t,rows}=E.guests(filters),share=E.concentration(filters.region);return `<div class="eyebrow">GUEST DESK · PEOPLE & REWARDS</div><h3>Who played, and what did it cost?</h3>${filterUI(true)}${scope(`FILTERED · ${periodText()} · ${filters.tier||'All opening tiers'} · ${filters.region||'All regions'} · carded play only · machine location filters do not apply`)}${kpis([['Wagered',money(t.coinIn)],['Paid back',money(t.payout)],['Guest net: payout − wagers',money(t.net)],['Comp economic cost',money(t.compCost)],['Player-month records',num(t.playerMonths)],['Ahead player-months',num(t.ahead)]])}${bars([['Wagers',t.coinIn],['Payouts',t.payout]],'Carded wagers and payouts')}<p class="note">A negative guest net means guests collectively lost that amount. Player-months are not unique people. Carded guests are a subset of the casino’s customers; these totals should not equal all-play machine meters.</p><details><summary>See each selected guest group</summary>${table(['Month','Tier','Region','Player-months','Wagers','Guest net','Comp cost'],rows.map(r=>[r[0],r[1],r[2],num(r[3]),money(r[6]),money(r[8]),money(r[10])]))}</details>${scope(`FIXED CONCENTRATION · Jan–Jun · ${filters.region||'All regions'} · global player ranks · month and tier filters do not apply`)}<p class="desk-note">${share==null?'No observations.':`${pct(share)} of this selection’s expected win comes from players in the property-wide top 10% by expected win.`} This describes concentration; it is not an invitation to target guests who lose heavily.</p><details><summary>Comp program timeline</summary>${scope('FIXED · Jan–Jun · all redemptions by gaming week · guest and period filters do not apply')}${table(['Week','Points / comp dollar','Economic cost','Redemptions'],D.compWeek.map(r=>[r[0].slice(0,10),r[1].toFixed(2),money(r[2]),num(r[3])]))}<p class="note">Economic cost differs from the face value guests redeem. Changes here are descriptive; guest mix and timing may also change.</p></details><div class="study-option"><b>Would you change rewards now—or test first?</b><p>A pilot can buy information, but setup costs money and a July gain is not established.</p><button class="outline" data-evidence="pilot">Open the experiment protocol ↗</button></div><button class="desk-link" data-evidence="guests">Guest-data definitions and evidence ↗</button>`;}
function forecast(){const schedule=window.AceDecision.schedule();const F=D.forecast,R=A.rolling,rows=R.intervals,max=Math.max(...rows.map(r=>r[3])),x=i=>40+i*690/(rows.length-1),y=v=>205-v/max*175,path=k=>rows.map((r,i)=>(i?'L':'M')+x(i)+','+y(r[k])).join(' '),band=rows.map((r,i)=>`${x(i)},${y(r[2])}`).concat([...rows].reverse().map((r,i)=>`${x(rows.length-1-i)},${y(r[3])}`)).join(' ');return `<div class="eyebrow">FORECAST DESK · SCHEDULE THE DISRUPTION</div><h3>Inspect on ${schedule.day}, ${schedule.label}.</h3><p class="desk-note">First eligible ${schedule.day} after the one-day inspection lead time. It has the lowest Jan–Apr mean wagers (${money(schedule.mean)}). Confirm technician coverage; this is a scheduling preference, not a forecast of inspection savings.</p>${scope('FIXED · Jan–Apr model fit · May–Jun original holdout · global filters do not apply')}${kpis([['Weekday-model MAE',money(F.maeWeekday)],['Flat-baseline MAE',money(F.maeBaseline)],['Holdout R²',F.r2Weekday]])}<svg class="desk-chart" viewBox="0 0 760 240" role="img" aria-label="May–June daily coin-in forecasts and actuals with nominal 90 percent prediction band"><polygon points="${band}" fill="#e7c77e" opacity=".2"/><path d="${path(1)}" stroke="#76c3e8" fill="none" stroke-width="2"/><path d="${path(4)}" stroke="#f2dfad" fill="none" stroke-width="2"/><text x="40" y="230">May 1</text><text x="680" y="230">June 30</text><text x="0" y="30">$${(max/1e6).toFixed(1)}m</text></svg><p class="note">Blue: forecast · gold: observed wagers · shaded: nominal 90% interval. MAE is average absolute error in dollars.</p><div class="desk-filters"><label>Choose a weekday for planned work<select id="scheduleDay" aria-label="Choose a weekday for planned work">${opts(Object.keys(F.weekdayMeans),'Tue')}</select></label></div><p id="scheduleResult" class="desk-note">Tuesday’s training-period mean is ${money(F.weekdayMeans.Tue)} in daily wagers. Compare it with ${money(Math.max(...Object.values(F.weekdayMeans)))} on the busiest training weekday. This supports scheduling, not a guaranteed July saving.</p><details><summary>Rolling tests and interval calibration</summary>${table(['Forecast month','Training through','Model MAE','Baseline MAE'],R.folds.map(r=>[r.month,r.trainEnd,money(r.maeModel),money(r.maeBaseline)]))}<p>Intervals use ${R.calibrationDays} earlier out-of-sample errors. May–June coverage: ${pct(R.coverage)}; mean width ${money(R.meanWidth)}. These diagnostics were added after the original holdout was viewed. They are not a fresh untouched validation set, and temporal dependence limits coverage guarantees.</p>${table(['Date','Forecast','Lower','Upper','Actual'],rows.map(r=>[r[0],...r.slice(1,5).map(money)]))}</details><button class="outline" data-evidence="forecast">Trace the model and decision ↗</button>`;}
const evidence={
 machines:['Fair comparisons before replacement','Machine-day meters → dated placement segments → ratio-of-sums expected win per available hour, availability and luck residual.','A quiet location, short exposure, repairs or payout variation can each explain low earnings. Same-game descriptive peers are not randomized controls.','build_data.py: machine aggregates and dated placements; validate_backend.py reconciles them to source meters.','q1'],
 movers:['Four moves, one strong location clue','Placements + active daily performance → same-configuration stayers → paired 7-day block bootstrap. All four movers are displayed.','Nonrandom moves, pre-period changes and customer switching limit causal interpretation. Back Forty already had an adverse trend before its closure.','advanced_analysis.py: movers and pretrend; validate_advanced.py.','moversStudy'],
 operations:['Downtime and switching','Hourly meters → leave-one-machine-out same-game/zone/weekday/hour rates → lost expected win → explicit switching sensitivity.','Sparse-cell fallback, correlated outages and unknown customer switching remain. This is gross expected win, not profit.','advanced_analysis.py: matched downtime; validate_advanced.py.','matchedLoss'],
 guests:['Guest outcomes and comp costs','Player-period records → month × opening tier × home region totals. Full-window player-level ranks supply concentration. Weekly redemption records supply the comp timeline.','Carded play only. Player-months are not unique guests. Comp costs are already in POS cost of goods and must not be deducted twice.','build_data.py: players, concentration, compWeek; validate_backend.py.','q4'],
 forecast:['A model that changes scheduling','Jan–Apr weekday means versus constant training mean → May–Jun holdout. Earlier rolling errors calibrate intervals.','Not a causal estimate of promotional or maintenance gains. Later diagnostic construction is disclosed; time dependence prevents guaranteed coverage.','build_data.py: forecast; advanced_analysis.py: rolling; validation scripts.','rollingStudy'],
 pilot:['A deferred experiment, not a promised return',`Plan ${num(A.pilot.perArm)} players per arm. Estimated MDE ${money(A.pilot.mde80)} (${A.pilot.mde80.toFixed(2)} dollars), 80% power, two-sided alpha .05. Randomize within tier × region; retain non-returners in assigned groups.`, 'Success: final 95% lower bound above zero and point estimate at least $5 per assigned player; return-rate lower 97.5% bound above −2 percentage points; no unresolved safety trigger. No early efficacy stopping. Pause for allocation failure, changed legacy balances, a confirmed policy-related harm incident, or three substantiated complaints.', 'Eligibility and variance must be rechecked. July 6–30 endpoint: theo + linked POS cash − COGS per assigned player. $4,000 setup; no extra awards or assumed July benefit. Compare property contribution too; do not extrapolate carded effects to all guests.','pilotProtocol'],
 plan:['A recommendation with a measurement plan','One M-1158 inspection is an information purchase. Reserve the remaining budget. Signage and a comp pilot remain priced alternatives.','Recovery is conditional, repairs require a separate quote, and zone gains may displace other play. No observed July outcomes are available.','Verify meters/paytable and document the finding first. If repair is separately authorized, compare same-game expected win per available hour before/after while monitoring availability, actual-versus-expected outcomes and whole-property contribution after costs.','decisionLab']
};
function openEvidence(key){const e=evidence[key]||evidence.machines;$('evidenceContent').innerHTML=`<div class="eyebrow">CLAIM → EVIDENCE → LIMITATION</div><h2 id="evidenceTitle">${e[0]}</h2><p class="desk-note">${e[1]}</p><h3>What could explain it otherwise?</h3><p>${e[2]}</p><h3>Reproduce or measure it</h3><p>${e[3]}</p><div class="actions"><a class="primary" href="dashboard.html#${e[4]}" target="_blank" rel="noopener">View the complete analysis ↗</a><a class="outline" href="evidence/CLAIMS_AND_EVIDENCE.md" target="_blank" rel="noopener">Claims appendix</a>${key==='pilot'?'<a class="outline" href="evidence/PILOT_PROTOCOL.md" target="_blank" rel="noopener">Full pilot protocol</a>':''}<a class="outline" href="evidence/source.zip">Download analysis code</a></div>`;$('evidenceDrawer').showModal();}
function render(){$('judgePlanControls')?.setAttribute('hidden','');document.querySelectorAll('.desk-tabs [data-desk]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.desk===tab));b.tabIndex=b.dataset.desk===tab?0:-1;});$('deskBody').setAttribute('aria-labelledby','desk-tab-'+tab);$('deskBody').innerHTML=tab==='brief'?brief():tab==='machines'?machines():tab==='movers'?movers():tab==='operations'?operations():tab==='guests'?guests():tab==='forecast'?forecast():`<div class="eyebrow">YOUR RECOMMENDATION</div><h3>Our funded recommendation</h3><p>Inspect M-1158 for <b>$1,200</b>; retain <b>$98,800</b>. Verify meters and payout configuration before authorizing a separately quoted repair. Monitor availability, expected win per available hour and property-wide contribution after costs; inspection does not guarantee recovery.</p><h3>Your optional what-if plan</h3><p>The controls below use your saved selections, which may differ from our recommendation. A zero-cost selection means keeping the budget; it does not change our submitted inspection recommendation.</p><div id="judgeScenarios">${window.AceGame.technicalHTML()}</div><button class="outline" data-evidence="plan">Read the analyst’s recommendation ↗</button> <button class="quiet" id="returnRounds">Return to guided rounds</button>`;$('deskBody').insertAdjacentHTML('beforeend','<div class="actions"><a class="desk-link" href="#stage" id="jumpToCase">Continue your guided round ↓</a></div>');$('jumpToCase').onclick=e=>{e.preventDefault();$('evidenceWorkspace').open=false;$('stage').scrollIntoView({behavior:'auto'});$('stage').focus({preventScroll:true});};if(tab==='plan')$('judgePlanControls')?.removeAttribute('hidden');$('deskBadges').innerHTML=[...visited].filter(x=>!['brief','plan'].includes(x)).map(x=>`<span>✓ ${tabs.find(t=>t[0]===x)[1].slice(2)} explored</span>`).join('');}
function show(key,scroll=true){$('evidenceWorkspace').open=true;tab=key;visited.add(tab);if(key==='plan'&&window.AceGame.getState()?.phase!=='plan')window.AceGame.openPlan();render();if(scroll){$('deskBody').scrollIntoView({behavior:'auto',block:'start'});$('deskBody').focus({preventScroll:true});}}
const host=document.createElement('section');host.id='investigationDesk';host.innerHTML=`<div class="judge-summary"><p><b>Your role: floor analytics lead.</b><br>Advise the manager before replacing ten machines.</p><button class="outline" data-evidence="plan">Decision summary & analysis ↗</button></div><nav class="desk-tabs" role="tablist" aria-label="Investigation desks">${tabs.map(([k,t],i)=>`<button id="desk-tab-${k}" role="tab" aria-controls="deskBody" data-desk="${k}" aria-selected="${k===tab}" tabindex="${k===tab?0:-1}"><span class="tab-number" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><span>${t.slice(2)}</span></button>`).join('')}</nav><div id="deskBadges" class="desk-badges" aria-label="Explored evidence"></div><article id="deskBody" class="desk-panel" role="tabpanel" tabindex="-1"></article>`;const workspace=document.createElement('details');workspace.id='evidenceWorkspace';workspace.innerHTML='<summary><span>Explore the supporting analysis</span><small>Filters, evidence and financial assumptions</small></summary>';workspace.append(host);$('stage').before(workspace);const controls=document.createElement('div');controls.id='judgePlanControls';controls.hidden=true;host.append(controls);function mountPlan(){const pieces=[...$('stage').querySelectorAll('.plan-custom,.lab')];if(pieces.length)controls.replaceChildren(...pieces);else if(window.AceGame.getState()?.phase!=='plan')controls.replaceChildren();}function refreshPlan(){if($('judgeScenarios'))$('judgeScenarios').innerHTML=window.AceGame.technicalHTML();}
const drawer=document.createElement('dialog');drawer.id='evidenceDrawer';drawer.className='evidence-drawer';drawer.setAttribute('aria-labelledby','evidenceTitle');drawer.innerHTML='<div class="dialog-head"><span>THE EVIDENCE FILE</span><button class="quiet" id="closeEvidence" aria-label="Close evidence">✕</button></div><div id="evidenceContent"></div>';document.body.append(drawer);$('closeEvidence').onclick=()=>drawer.close();
document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;if(b.id==='returnRounds'){$('evidenceWorkspace').open=false;window.AceGame.resumeCases();$('stage').scrollIntoView({behavior:'auto'});return;}if(b.dataset.original){filters={from:0,to:5,zone:'',bank:'',tier:'',region:''};selected=b.dataset.original;metric='houseWin';show('machines');return;}if(b.dataset.desk){show(b.dataset.desk);return;}if(b.dataset.evidence){if(b.closest('.case-evidence'))show(b.dataset.evidence==='pilot'?'guests':b.dataset.evidence);else openEvidence(b.dataset.evidence);return;}if(b.hasAttribute('data-reset-filters')){filters={from:0,to:5,zone:'',bank:'',tier:'',region:''};render();}if(b.dataset.machine){selected=b.dataset.machine;render();}if(b.dataset.mover){mover=b.dataset.mover;render();}if(b.dataset.judgment){judgments[selected]=b.dataset.judgment;try{localStorage.setItem('ace-investigation-notes',JSON.stringify(judgments));}catch{}render();}});
host.addEventListener('change',e=>{const id=e.target.id,v=e.target.value;if(id==='deskFrom'){filters.from=+v;filters.to=Math.max(filters.to,+v);}if(id==='deskTo'){filters.to=+v;filters.from=Math.min(filters.from,+v);}if(id==='deskZone'){filters.zone=v;filters.bank='';}if(id==='deskBank')filters.bank=v;if(id==='deskTier')filters.tier=v;if(id==='deskRegion')filters.region=v;if(id==='rankMetric'){metric=v;selected='';}if(id==='deskMover')mover=v;if(id==='movePeriod')period=v;if(id==='scheduleDay'){$('scheduleResult').textContent=`${v}: ${money(D.forecast.weekdayMeans[v])} mean daily wagers in Jan–Apr training. Schedule disruptive work with this demand pattern, operational constraints and uncertainty in mind. This is not a promised July outcome.`;return;}if(id!=='deskRetention')render();});
host.addEventListener('input',e=>{if(e.target.id!=='deskRetention')return;retention=+e.target.value;$('retentionLabel').textContent=retention+'%';$('retentionResult').innerHTML=bars([['Machine-level',A.matchedDowntime.lostTheo],['Property-level',A.matchedDowntime.lostTheo*(1-retention/100)]],'Machine and property-level expected win forgone')+`<p class="desk-note">At ${retention}% retention, ${money(A.matchedDowntime.lostTheo*(1-retention/100))} expected win is forgone property-wide, before incremental costs.</p>`;});

let lastCase=window.AceGame.getState()?.order[window.AceGame.getState()?.index];
document.addEventListener('ace:render',e=>{mountPlan();if(e.detail.phase==='plan'||e.detail.phase==='result'){tab='plan';render();}else if(e.detail.caseId!==lastCase){lastCase=e.detail.caseId;tab=({leak:'machines',mover:'movers',downtime:'operations',trend:'movers',model:'forecast',pilot:'guests'})[lastCase]||'brief';visited.add(tab);render();}});
host.querySelector('.desk-tabs').addEventListener('keydown',e=>{const keys=['ArrowRight','ArrowLeft','Home','End'];if(!keys.includes(e.key))return;e.preventDefault();const i=tabs.findIndex(t=>t[0]===tab),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;show(tabs[next][0],false);$('desk-tab-'+tabs[next][0]).focus();});
window.AceDesk={show,mountPlan,refreshPlan,evidence:openEvidence,getFilters:()=>({...filters}),getNotes:()=>({...judgments})};mountPlan();render();
})();
